Here's a TypeScript function that validates a user's password with specific requirements:

```typescript
interface PasswordValidation {
    isValid: boolean;
    errors: string[];
}

function validatePassword(password: string): PasswordValidation {
    const errors: string[] = [];

    if (password.length < 8) {
        errors.push('Password must be at least 8 characters');
    }
    if (!/[a-z]/.test(password)) {
        errors.push('Password must contain a lowercase letter');
    }
    if (!/[A-Z]/.test(password)) {
        errors.push('Password must contain an uppercase letter');
    }
    if (!/\d/.test(password)) {
        errors.push('Password must contain a number');
    }
    if (!/[!@#$%^&*()_+\-=\[\]{};:"\'|,.<>/?]/.test(password)) {
        errors.push('Password must contain a special character');
    }

    return {
        isValid: errors.length === 0,
        errors,
    };
}

// Example usage:
const tests = ['weak', 'Weak1', 'Strong1!Pass', 'NoSpec1al'];
tests.forEach(pwd => {
    const result = validatePassword(pwd);
    console.log(`'${pwd}': ${result.isValid ? 'VALID' : 'INVALID'}`);
    if (!result.isValid) {
        result.errors.forEach(err => console.log(`  - ${err}`));
    }
});

// Alternative with regex pattern match:
const PASSWORD_PATTERN = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{};:"\'|,.<>/?]).{8,}$/;

function validatePasswordPattern(password: string): boolean {
    return PASSWORD_PATTERN.test(password);
}
```

This function checks for minimum length, lowercase, uppercase, digit, and special character requirements, returning detailed error messages for each failed check.
